import java.util.*;
import java.io.*;

public class Main {
    static long[] shortestDistances(int n, int[][] edges) {
        // Write your solution here
        // Return n distances from node 0 (-1 when unreachable)
        return new long[n];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int[][] edges = new int[m][3];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < 3; j++) {
                in.nextToken();
                edges[i][j] = (int) in.nval;
            }
        }
        long[] dist = shortestDistances(n, edges);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < dist.length; i++) sb.append(dist[i]).append(i + 1 < dist.length ? " " : "\n");
        System.out.print(sb);
    }
}
